//----------  file compile_output.c  ----------
//    output abstraction for macrocode/buffers
//---------------------------------------------

#if defined mdebug
#include <stdio.h>
#endif
#include <stddef.h>
#include <stdint.h>
#include "compile_output.h"
#include "avl_identifiers.h"
#include "macrocode.h"
#include "function_pool.h"

// Where generated bytes and addresses go right now:
// the macrocode text directly, or the left/right part buffer of the stored sentence
// current_sentence (sentences are kept in memory so they can be optimized later).
static T_OUTPUT_MODE current_mode = OUTPUT_MACROCODE;
static T_STORED_SENTENCE *current_sentence = NULL;

// Resets the output to direct macrocode generation.
void compile_output_init(void)
{
    current_mode = OUTPUT_MACROCODE;
    current_sentence = NULL;
    return;
}

// Selects the output mode together with the sentence that receives the output.
void compile_output_set_mode(T_OUTPUT_MODE mode, T_STORED_SENTENCE *sentence)
{
    current_mode = mode;
    current_sentence = sentence;
    return;
}

// Changes only the target sentence; the mode stays.
void compile_output_set_current_sentence(T_STORED_SENTENCE *sentence)
{
    current_sentence = sentence;
    return;
}

// Continues in the right part buffer of the current sentence (no effect without one).
void compile_output_switch_to_right_part(void)
{
    if (current_sentence != NULL)
        current_mode = OUTPUT_RIGHT_PART;
    return;
}

// Returns to direct macrocode output and forgets the current sentence.
void compile_output_switch_to_macrocode(void)
{
    current_mode = OUTPUT_MACROCODE;
    current_sentence = NULL;
    return;
}

// Announces the start of a statement (its operator code is output next). Only the left part
// keeps the boundaries of the statements: the optimizer of the function pool needs them.
void compile_output_statement_start(void)
{
    if (current_mode == OUTPUT_LEFT_PART && current_sentence != NULL)
        sentence_mark_statement_left(current_sentence);
    return;
}

// Outputs one byte of an operator or its operand to the current destination.
void compile_output_byte(uint8_t byte)
{
#if defined mdebug
    fprintf(stderr, "compile_output_byte: byte=0x%02X mode=%d sentence=%p\n", byte, current_mode, (void *)current_sentence);
#endif
    switch (current_mode)
    {
    case OUTPUT_MACROCODE:
        macrocode_byte(byte);
        break;
    case OUTPUT_LEFT_PART:
        if (current_sentence != NULL)
            sentence_append_byte_left(current_sentence, byte);
        break;
    case OUTPUT_RIGHT_PART:
        if (current_sentence != NULL)
            sentence_append_byte_right(current_sentence, byte);
    }
    return;
}

// Outputs a reference to a label to the current destination.
void compile_output_address(T_LABEL *label)
{
#if defined mdebug
    fprintf(stderr, "compile_output_address: label=%p mode=%d sentence=%p\n", (void *)label, current_mode, (void *)current_sentence);
#endif
    switch (current_mode)
    {
    case OUTPUT_MACROCODE:
        macrocode_address(label);
        break;
    case OUTPUT_LEFT_PART:
        if (current_sentence != NULL)
            sentence_append_address_left(current_sentence, label);
        break;
    case OUTPUT_RIGHT_PART:
        if (current_sentence != NULL)
            sentence_append_address_right(current_sentence, label);
    }
    return;
}

// Defines a label at the current position. Only macrocode output has labels;
// buffered parts get theirs when the sentence is written out.
void compile_output_label(T_LABEL *label)
{
    if (current_mode == OUTPUT_MACROCODE)
        macrocode_label(label);
    return;
}

//----------  end of file compile_output.c  ----------
